+                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                        <small>@entry.StartDate?.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</small>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p class="mb-0 mt-1">@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            <!-- References Review -->
+            <div class="review-section">
+                <h4>References <a href="javascript:void(0)" @onclick="() => GoToStep(2)" class="edit-link">Edit</a></h4>
+                @foreach (var reference in _references)
+                {
+                    <div class="mb-2 ps-3 border-start">
+                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                        <small>@reference.Email | @reference.Phone</small>
+                    </div>
+                }
+            </div>
+
+            <!-- Cover Letter Review -->
+            <div class="review-section">
+                <h4>Cover Letter <a href="javascript:void(0)" @onclick="() => GoToStep(3)" class="edit-link">Edit</a></h4>
+                <p style="white-space: pre-wrap;">@_coverLetter</p>
+            </div>
+
+            <div class="form-nav">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                    @if (_isSubmitting)
+                    {
+                        <span>Submitting...</span>
+                    }
+                    else
+                    {
+                        <span>Submit Application</span>
+                    }
+                </button>
+            </div>
+        </div>
+    }
+}
+
+@code {
+    private readonly string[] _stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+    private int _currentStep = 0;
+    private string _errorMessage = string.Empty;
+    private bool _isValidating = false;
+    private bool _isSubmitting = false;
+    private bool _submitted = false;
+    private int _applicationId = 0;
+
+    // Step 1 fields
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+
+    // Step 2 fields
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3 fields
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 fields
+    private string _coverLetter = string.Empty;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == _currentStep) return "active";
+        if (stepIndex < _currentStep) return "completed";
+        return "future";
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step < _currentStep)
+        {
+            _errorMessage = string.Empty;
+            _currentStep = step;
+        }
+    }
+
+    private async Task NextFromPersonalInfo()
+    {
+        _errorMessage = string.Empty;
+
+        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
+            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+        {
+            _errorMessage = "All fields are required.";
+            return;
+        }
+
+        _isValidating = true;
+        try
+        {
+            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+            if (!emailValid)
+            {
+                _errorMessage = "Please enter a valid email address.";
+                return;
+            }
+            _currentStep = 1;
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    private void NextFromWorkHistory()
+    {
+        _errorMessage = string.Empty;
+
+        foreach (var entry in _workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
+            {
+                _errorMessage = "Company, Job Title, and Start Date are required for each position.";
+                return;
+            }
+        }
+
+        _currentStep = 2;
+    }
+
+    private void NextFromReferences()
+    {
+        _errorMessage = string.Empty;
+
+        foreach (var reference in _references)
+        {
+            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship)
+                || string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
+            {
+                _errorMessage = "All reference fields are required.";
+                return;
+            }
+        }
+
+        _currentStep = 3;
+    }
+
+    private void NextFromCoverLetter()
+    {
+        _errorMessage = string.Empty;
+        _currentStep = 4;
+    }
+
+    private void PreviousStep()
+    {
+        _errorMessage = string.Empty;
+        if (_currentStep > 0) _currentStep--;
+    }
+
+    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (_workEntries.Count > 1) _workEntries.RemoveAt(index);
+    }
+
+    private void ToggleCurrent(int index, bool isCurrent)
+    {
+        _workEntries[index].IsCurrent = isCurrent;
+        if (isCurrent) _workEntries[index].EndDate = null;
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3) _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (_references.Count > 2) _references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _errorMessage = string.Empty;
+
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workHistory = new WorkHistory(_workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)
+            ).ToList());
+            var references = _references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
+            ).ToList();
+            var application = new JobApplication(personal, workHistory, references, _coverLetter);
+
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime? StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+

toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 2rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.25rem;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

.form-section {
    max-width: 700px;
    margin: 1rem auto;
}

.form-nav {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    gap: 1rem;
}

.review-section {
    border-bottom: 1px solid #dee2e6;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section h4 {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.edit-link {
    font-size: 0.85rem;
    font-weight: normal;
}

